#!/usr/bin/env bash
# PREREG_V8F_DAGGER2 on box 2: DAgger ITERATION 2. The own-state bank is generated by DAG (M2b_s<S>_dag, the iteration-1 fine-tune), and the two new arms are fine-tuned FROM DAG:
#   DAG2   = DAG_s<S> + 3,000 steps with --dagger-p 0.1 on the iteration-2 bank (--init-ckpt = DAG's checkpoint, the bank's generator)
#   DAG2-0 = the same argv with --dagger-p 0 (no bank / hash / seed flags)
# This file is GENERATED from chain_v8f_dag2.sh.in by make_chain.py (DAG's checkpoint / argv.json / summary.json sha256 values are copied from v8f-dagger/M2b_s<S>_dag/SHA256SUMS.txt, never retyped; the export list from
# export_closure.json); the template is itself the DAG chain's template with exact-count edits. BUILT, NOT LAUNCHED: it runs only on the PI's go.
# One chain, in PREREG_V8F_DAGGER2's order, ONE job at a time on box 2 (mk_v8f_job.py, SAFE MODE):
#   0. the DAG-READ PREDICATE (before anything is touched): E:/Projects/TanitAD-artifacts/v8f-dagger-t1/read/DAG_READ.json must hash to the PINNED sha256 (DAG_READ_SHA below), its OUTCOME must be ROBUST (claim row H-V8F-DAGGER-1, every
#      control PASS, exactly one matching table row). Any other outcome, another file, a failed control, an unreadable file => ZZV8FMINI-STOP, nothing touched. Read again, byte-identically (sha256), right before the gates.
#   1. wait for the predecessor chain that holds box 2 (AFTER_OUT, REQUIRED, no default: ZZV8FMINI-DONE -> go, ZZV8FMINI-STOP -> stop), take BOX2_BUSY atomically, refresh box 2's code from the REMOTE tip with a SMALL export
#      (only what the queue reads: the closure of the four entry scripts + the repo data files they open; repo_v8fdag2_tip.tar, <= 300 MB asserted; the DAG chain's 1.45 GB tar is neither deleted nor overwritten), sha-check the key files,
#      md5-check the v9 releases, assert box 2's DAG_s<S> checkpoint, argv.json and summary.json (sha256) are the banked DAG run's (the bank generator and the --init-ckpt of all four arms)
#   2. BANK s0, BANK s1 (`bankdag2`: four clip-sharded generators of DAG_s<S> + merge, into $R/dagger_bank_dag2/s<S>, never the iteration-1 dagger_bank); the SMALL files are fetched first (bank.json, PROVENANCE.json,
#      bank_stage.log, the 4 shard provenance files: all the judge reads); box 2's bank.json sha256 == the pulled file's
#   3. COVERAGE + bank controls (`v8f_dag2_chain_checks.py bank-judge`, the DAG judge unchanged except that K-B2 now reads DAG's checkpoint sha256): a failed CONTROL = REFUSED; with every control passing, the eligible fraction of TRAIN
#      windows >= 0.5 at BOTH seeds, else BLOCKED and the chain STOPS here: no gate is queued and nothing is trained (ZZDAG2-BLOCKED + ZZV8FMINI-STOP BLOCKED)
#   3b. PUBLISH THE BANKS to the dev box (`publish_bank_one`, only after the judge passed), per seed, into $ART/bank_s<S>/: the FOUR kinds the dev-box reader needs + bank_stage.log (11 files), SHA256SUMS.txt written LAST
#   4. ALL FOUR GATES FIRST (`gatedag dag2|dag20`, the trainer's own in-process gate), each pulled and asserted HERE (gate_dag2_assert.py), in the order DAG2 s0, DAG2-0 s0, DAG2 s1, DAG2-0 s1. The bank's sha256 is computed by box 2 from
#      bank.json INSIDE the gate stage; the gate stage PINS the training argv; the chain asserts the pin equals the queue's planned training line and writes the LAUNCH-GATE TOKEN (never by hand, only after every assertion passes)
#   5. the four runs, in order: `traindag` (3,000 steps from DAG_s<S>) -> `evaldag` (the standard T0 eval, tag M2b-dag2_s<S> / M2b-dag20_s<S>) -> pull to $ART/<run>/ (sha256 in SHA256SUMS.txt) -> the run record is asserted
#      (argv.json == the pinned argv == the planned one) -> the REACHED control is PRINTED (DAG2: dagger_n / dagger_eligible in 0.1 +- 0.02; DAG2-0: exactly 0)
#   NOT HERE: the T1-kin rollouts, K4's fresh-age T0 comparator and the reader: dev-box CPU.
#   chain_v8f_dag2.sh --dry-run               PRINTS every stage line, the planned token argv_sha256 values and the checks, touches nothing (the bank sha256 is a placeholder unless DAG_DRY_SHA0 / DAG_DRY_SHA1 are set)
#   chain_v8f_dag2.sh --judge-only D0 D1      OFFLINE: the DAG-read predicate and the COVERAGE / controls judge on two local dirs of PULLED bank files; prints exactly the markers the real chain would, touches nothing
#   chain_v8f_dag2.sh --check-tree ROOT       OFFLINE: the tip-carries-the-lever greps (trainer + generator + the queue insertions), applied to a directory instead of `git show <tip>:`
#   AFTER_OUT=<log> chain_v8f_dag2.sh         the real run
# Markers in ITS OWN log (chain_v8f_dag2.out): ZZV8FMINI-DONE / ZZV8FMINI-STOP, which v8f_guard_dag2.sh's anchored end test knows. Script polling, not model turns.
# TIMEOUTS (polls of 30 s): bank 1,200 (10 h; ESTIMATED 1.1-1.5 h), gate 120, train 1,320 (11 h, one above the guard's 10 h cap, so the GUARD ends a slow run), eval 600.
PK="TanitAD Research Lab/Architecture & Inference/Research/2026-10-17-v8f-mini"
R=D:/tanitad/runs/v8f_mini_full
# DAG's checkpoints, argv.json and summary.json (v8f-dagger/M2b_s<S>_dag/SHA256SUMS.txt), COPIED by make_chain.py
CKPT_SHA=(d186fd0bcfa7ee9fbfe5c9de543fe85edda7c3e6b9c56c898958f027ae2b8cb1 1d12ec2eb825990d57dcc45dda50b5178d1d733961b47ab0e3d50e6155fa39ef)      # DAG_s0 / DAG_s1 ckpt_last.pt
ARGV_SHA=(50e9d01d3dee881367a4eb1433903b05cc093c83d7bccc32a518e2290d9f3ce3 38a591e3e5a05c6f72669a268aaf99591af167758296720d650c46ebba4541b3)      # DAG_s0 / DAG_s1 argv.json
SUMM_SHA=(06ae1555ad278f4d323fdae33987f079d5b85005f35bddfd56dbc362d6ad4b41 e77f9e0125695ff01ff8fa12898663fbb9a32672160fded821d9a32d86ed6b6f)      # DAG_s0 / DAG_s1 summary.json
RUNS=("dag2 0" "dag20 0" "dag2 1" "dag20 1")      # PREREG_V8F_DAGGER2's order (bank s0, bank s1, then DAG2 s0, DAG2-0 s0, DAG2 s1, DAG2-0 s1); ARM SEED
PY=C:/Users/Admin/venvs/tanitad/Scripts/python.exe
ART=${DAG2_ART:-/e/Projects/TanitAD-artifacts/v8f-dagger2}
DAG1_DIR=${DAG2_DAG1_DIR:-/e/Projects/TanitAD-artifacts/v8f-dagger}      # the DAG run's pulled artifacts (iteration 1): read-only here
DAG_READ=${DAG2_DAG_READ:-/e/Projects/TanitAD-artifacts/v8f-dagger-t1/read/DAG_READ.json}
DAG_READ_SHA=3393fdd56bd561fd5181a8219d2c75d700036b9373da6ec12a8bcba51decde3d      # PINNED: PREREG_V8F_DAGGER2 is licensed by exactly this read (outcome ROBUST)
PVAL=0.1      # DAG2's P, fixed by PREREG_V8F_DAGGER2 section 4 (the queue refuses any other)
B=/c/Users/Admin/box2_ship; L=$B/logs; E=$L/v8f_dag2
HERE_SHIP=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)      # the two helper scripts sit beside this file (box2_ship when installed; dagq/box2_ship while staged, which is what the self-test runs)
CHECKS=$HERE_SHIP/v8f_dag2_chain_checks.py; ASSERT=$HERE_SHIP/gate_dag2_assert.py
DAG_STEPS=3000
rn() { echo "M2b_s${2}_${1}"; }       # rn <arm> <seed>: the run's directory under $R (M2b_s0_dag2, M2b_s0_dag20, ...)
rt() { echo "M2b-${1}_s${2}"; }       # rt <arm> <seed>: the run's eval tag
rg() { echo "gate_M2b-${1}_s${2}"; }  # rg <arm> <seed>: the run's gate directory under $R
# the lever-in-the-tip checks: "<file>|<grep -E pattern>". The pattern for the loop line is anchored on its indentation: the same text also sits in a COMMENT.
LEVER=(
  'stack/scripts/v8f_mini_train.py|add_argument\("--dagger-p"'
  'stack/scripts/v8f_mini_train.py|add_argument\("--dagger-bank"'
  'stack/scripts/v8f_mini_train.py|add_argument\("--dagger-bank-sha256"'
  'stack/scripts/v8f_mini_train.py|add_argument\("--dagger-seed"'
  'stack/scripts/v8f_mini_train.py|"dagger_p": "dagger:dagger_p"'
  'stack/scripts/v8f_mini_train.py|"dagger_bank": "dagger:dagger_bank"'
  'stack/scripts/v8f_mini_train.py|"dagger_bank_sha256": "dagger:dagger_bank_sha256"'
  'stack/scripts/v8f_mini_train.py|"dagger_seed": "dagger:dagger_seed"'
  'stack/scripts/v8f_mini_train.py|bad \+= bad_dagger\(a, dag, model\.cfg, data_info\)'
  'stack/scripts/v8f_mini_train.py|^ +dagp = dagger_probe\(model, probe, cfg, dag\)'
  'stack/scripts/v8f_mini_train.py|^ +b = dag\.apply\(b, step\)'
  'stack/scripts/v8f_mini_train.py|"dagger_n": dag_tot\["n"\]'
  'stack/scripts/v8f_mini_train.py|^class LRSchedule'
  'stack/tanitad/data/v8f_dagger.py|^class DaggerSwap'
  'stack/tanitad/data/v8f_dagger.py|NAV_REBUILD_INVALID = False'
  'stack/scripts/v8f_dagger_bank.py|^def cmd_merge'
  'stack/scripts/v8f_dagger_bank.py|window_start=cfg\.window_start'
  'stack/scripts/v8f_dagger_queue_tool.py|^def cmd_bank'
  # the DAGGER2 queue insertions (the queue file on the tip; `.` = a backslash)
  "$PK/code/v8f_mini_box2_queue.cmd|^:bankdag2"
  "$PK/code/v8f_mini_box2_queue.cmd|^:dag2arm"
  "$PK/code/v8f_mini_box2_queue.cmd|goto :bankdag2"
  "$PK/code/v8f_mini_box2_queue.cmd|goto :dag2arm"
  "$PK/code/v8f_mini_box2_queue.cmd|DAGS=dag20"
  "$PK/code/v8f_mini_box2_queue.cmd|dagger_bank_dag2"
  "$PK/code/v8f_mini_box2_queue.cmd|DAGGEN=%RUNSM%.M2b_s%~2_dag"
  "$PK/code/v8f_mini_box2_queue.cmd|init-ckpt .*M2b_s%~2_dag.ckpt_last.pt"
  "$PK/code/v8f_mini_box2_queue.cmd|bankdag2 SEED"
)
STAGES=(bankdag gatedag traindag evaldag dagname dagarm prepdag bankdag2 dag2arm)
lever_check() {   # lever_check <git tip | tree ROOT>: 0 iff every LEVER pattern is in its file
  local mode=$1 ref=$2 rec f pat miss=0
  for rec in "${LEVER[@]}"; do
    f=${rec%%|*}; pat=${rec#*|}
    if [ "$mode" = tree ]; then grep -qE -- "$pat" "$ref/$f" 2>/dev/null; else git -C $MIRROR show "$ref:$f" 2>/dev/null | grep -qE -- "$pat"; fi \
      || { echo "MISSING in $f: $pat"; miss=$((miss+1)); }
  done
  [ $miss = 0 ]
}
dry_stage() {   # dry_stage <queue file> <bank sha or ""> <stage args...>: the line(s) the queue prints for a stage under V8F_DRYRUN, with BOX 2's paths pinned (the dev box's environment must not decide what box 2 will run). DAGSHA_DRY = the sha256 of the PULLED bank.json
  local qf=$1 sha=$2; shift 2
  local w=${TMPDIR:-/tmp}/v8fdag2_dry_$$.cmd
  { printf '@echo off\r\nset V8F_DRYRUN=1\r\nset "REPO=%s"\r\nset "PY=%s"\r\nset "CACHEFULL=%s"\r\nset "V9=%s"\r\nset "RUNSM=%s"\r\n' 'D:\tanitad\repo' 'D:\tanitad\venv\Scripts\python.exe' 'D:\tanitad\cache_full' 'D:\tanitad\data\v9' 'D:\tanitad\runs\v8f_mini_full'
    [ -z "$sha" ] || printf 'set "DAGSHA_DRY=%s"\r\n' "$sha"
    printf 'call "%s" %s\r\n' "$(cygpath -w "$qf")" "$*"; } > "$w"
  MSYS_NO_PATHCONV=1 cmd /c "$(cygpath -w "$w")" </dev/null | tr -d '\r'
  rm -f "$w"
}
plan() {   # plan <queue file> <arm> <seed> <bank sha or "">: GL / TL / EL = the lines the queue prints for the run's gate / train / eval stages. rc 1 if a stage prints no trainer / eval line
  local parg=""; [ "$2" = dag2 ] && parg=$PVAL
  GL=$(dry_stage "$1" "$4" gatedag $2 $3 $parg | grep -a 'v8f_mini_train.py'); TL=$(dry_stage "$1" "$4" traindag $2 $3 $parg | grep -a 'v8f_mini_train.py')
  EL=$(dry_stage "$1" "" evaldag $2 $3 | grep -a 'v8f_mini_eval.py')
  [ -n "$GL" ] && [ -n "$TL" ] && [ -n "$EL" ]
}
dag_pred() {   # dag_pred: the DAG-read predicate on the PINNED read file; sets DAG_OUT / DAG_RC / DAG_NAME / DAGR_SHA; prints the verdict. rc 0 = ROBUST (run), 4 = a usable read that is not ROBUST (stop), 2 = not the pinned read / not usable
  DAG_OUT=$($PY "$(cygpath -m $CHECKS)" dag-predicate "$(cygpath -m "$DAG_READ")" --expect-sha $DAG_READ_SHA); DAG_RC=$?
  echo "DAG-read predicate (rc $DAG_RC): $DAG_OUT"
  [ $DAG_RC = 0 ] || return $DAG_RC
  DAGR_SHA=${DAG_OUT##* }; DAG_NAME=${DAG_OUT% *}
}
judge_banks() {   # judge_banks <dir s0> <dir s1>: controls first (REFUSED), then COVERAGE (BLOCKED); prints the judge line and the markers; returns 0 / 3 / 2
  local o rc
  o=$($PY "$(cygpath -m $CHECKS)" bank-judge --banked-sha0 ${CKPT_SHA[0]} --banked-sha1 ${CKPT_SHA[1]} --seed0-dir "$(cygpath -m "$1")" --seed1-dir "$(cygpath -m "$2")"); rc=$?
  echo "$o" | cut -c1-1800
  case $rc in
    0) echo "ZZDAG2-JUDGE-PASS every bank control passed and the eligible fraction of TRAIN windows is >= 0.5 at both seeds: the four gates are queued next" ;;
    3) echo "ZZDAG2-BLOCKED outcome BLOCKED (PREREG_V8F_DAGGER2 outcome table): COVERAGE < 0.5 at seed(s) $(echo "$o" | sed -n 's/.*"blocked_seeds": \(\[[^]]*\]\).*/\1/p'): no gate was queued, nothing was trained; next is the rejoin-target form, under its own PREREG" ;;
    *) echo "ZZDAG2-REFUSED a bank control failed: $(echo "$o" | sed -n 's/.*"refused_because": \(\[.*\]\), "seeds".*/\1/p' | cut -c1-600) (REFUSED: fix and re-run)" ;;
  esac
  return $rc
}
argvsha() {   # argvsha <line file>: launch_gate.argv_sha256 of the TRAINING argv of a printed line
  $PY "$(cygpath -m $CHECKS)" argv-sha "$(cygpath -m "$1")"
}
bank_fetch_small() {   # bank_fetch_small <seed>: the SMALL files of the seed's bank (all the judge reads), pulled to $ART/bank_s<seed>; box 2's bank.json sha256 must equal the pulled file's. A SHA256SUMS.txt of an earlier attempt is removed FIRST: the sums are written last, and only over a set that verified.
  local s=$1 d="$ART/bank_s$1" k f rs ls
  rm -f "$d/SHA256SUMS.txt"
  for f in bank.json PROVENANCE.json bank_stage.log; do pull "dagger_bank_dag2/s$s/$f" "$d"; done
  for k in 0 1 2 3; do pull "dagger_bank_dag2/s$s/shard_00${k}of004.provenance.json" "$d"; done
  rs=$(rsha "$R/dagger_bank_dag2/s$s/bank.json" SHA256); ls=$(sha256sum "$d/bank.json" | cut -c1-64)
  [ -n "$rs" ] && [ "$rs" = "$ls" ] || stop "bank s$s: box 2's bank.json sha256 '$rs' != the pulled file's '$ls'"
  BSHA[$s]=$ls
  echo "$(date '+%m-%d %H:%M') bank s$s: the small files (bank.json, PROVENANCE.json, bank_stage.log, 4 shard provenance) fetched to $d (bank.json sha256 $ls); the shard npz follow only if the controls pass"
}
publish_bank_one() {   # publish_bank_one <seed>: AFTER the judge passed. The shard npz of the seed's bank, then SHA256SUMS.txt over ALL the published files -- the mechanism the checkpoints and eval outputs use: pull, sha256 measured on box 2 and here, sha256sum | tee SHA256SUMS.txt written LAST
  local s=$1 d="$ART/bank_s$1" f rs ls names all v
  names=$($PY "$(cygpath -m $CHECKS)" bank-files "$(cygpath -m "$d")" --kind shard_npz) || stop "bank s$s: cannot name the shard npz from the pulled bank.json / PROVENANCE.json"
  names=${names//$'\r'/}                                  # belt and braces: a CR left in a file name would make every pull below fail on a name that does not exist
  for f in $names; do
    pull "dagger_bank_dag2/s$s/$f" "$d"
    ls=$(sha256sum "$d/$f" | cut -c1-64); rs=$(rsha "$R/dagger_bank_dag2/s$s/$f" SHA256)
    [ -n "$rs" ] && [ "$rs" = "$ls" ] || stop "bank s$s: box 2's $f sha256 '$rs' != the pulled file's '$ls'"
  done
  v=$($PY "$(cygpath -m $CHECKS)" bank-verify "$(cygpath -m "$d")") || stop "bank s$s: the pulled files do not verify, nothing was sealed: $(echo "$v" | cut -c1-600)"
  all=$($PY "$(cygpath -m $CHECKS)" bank-files "$(cygpath -m "$d")" --kind all) || stop "bank s$s: cannot name the files to seal"
  all=${all//$'\r'/}
  ( cd "$d" && sha256sum $all | tee SHA256SUMS.txt )
  v=$($PY "$(cygpath -m $CHECKS)" bank-verify "$(cygpath -m "$d")" --require-sums) || { rm -f "$d/SHA256SUMS.txt"; stop "bank s$s: SHA256SUMS.txt does not verify (removed): $(echo "$v" | cut -c1-600)"; }
  echo "$(date '+%m-%d %H:%M') bank s$s pulled to $d ($(echo "$v" | sed -n 's/.*"n_files": \([0-9]*\).*/\1/p') files: PROVENANCE.json, bank.json, shard provenance, shard npz, bank_stage.log; sha256 in SHA256SUMS.txt; bank.json sha256 ${BSHA[$s]})"
}
if [ "${1:-}" = "--check-tree" ]; then
  [ -d "${2:-}" ] || { echo "usage: --check-tree ROOT"; exit 2; }
  MIRROR=none; if lever_check tree "$2"; then echo "lever check: every one of ${#LEVER[@]} patterns is in $2"; exit 0; fi; echo "lever check: FAILED"; exit 1
fi
if [ "${1:-}" = "--judge-only" ]; then
  [ -d "${2:-}" ] && [ -d "${3:-}" ] || { echo "usage: --judge-only DIR_S0 DIR_S1"; exit 2; }
  dag_pred || { echo "ZZV8FMINI-STOP the DAG-read predicate: $DAG_OUT"; exit 1; }
  judge_banks "$2" "$3"; jr=$?
  [ $jr = 0 ] || echo "ZZV8FMINI-STOP $([ $jr = 3 ] && echo BLOCKED || echo REFUSED): no gate was queued"
  exit $jr
fi
if [ "${1:-}" = "--publish-only" ]; then   # OFFLINE: the real bank_fetch_small -> judge -> publish_bank_one on a LOCAL stand-in for box 2 (FAKE/dagger_bank_dag2/s0 and s1); pull/rsha/stop are the only things replaced. Refuses the real artifact directory.
  FAKE=${2:-}
  [ -d "$FAKE/dagger_bank_dag2/s0" ] && [ -d "$FAKE/dagger_bank_dag2/s1" ] || { echo "usage: DAG2_ART=<scratch dir> $0 --publish-only FAKE_BOX_ROOT   (FAKE_BOX_ROOT/dagger_bank_dag2/s0 and s1 stand for box 2's $R/dagger_bank_dag2/s<S>)"; exit 2; }
  [ -n "${DAG2_ART:-}" ] || { echo "ZZV8FMINI-STOP --publish-only needs DAG2_ART set to a scratch directory (it never writes the real $ART)"; exit 1; }
  HASHROOT=${FAKE_HASH_ROOT:-$FAKE}                   # box 2's own hash is measured here (a test points it at a tampered copy to show a transfer that corrupts is caught)
  stop() { echo "ZZV8FMINI-STOP $*"; exit 1; }
  pull() { mkdir -p "$2"; cp "$FAKE/$1" "$2/" || stop "pull $R/$1"; }
  rsha() { sha256sum "$HASHROOT/${1#$R/}" 2>/dev/null | cut -c1-64; }
  declare -a BSHA
  for s in 0 1; do bank_fetch_small $s; done
  judge_banks "$ART/bank_s0" "$ART/bank_s1"; jr=$?
  [ $jr = 0 ] || stop "$([ $jr = 3 ] && echo BLOCKED || echo REFUSED) at the bank stage (judge rc $jr): no shard npz was pulled, no gate was queued"
  for s in 0 1; do publish_bank_one $s; done
  echo "ZZDAG2-PUBLISH-ONLY-DONE both banks published"
  exit 0
fi
if [ "${1:-}" = "--dry-run" ]; then
  QF=${V8F_QUEUE:-}
  if [ -z "$QF" ]; then
    MIRROR=${MIRROR:-/c/Users/Admin/tanitad-push}; BR=${BR:-agent/arch-inf-20260803}
    T=$(git -C $MIRROR ls-remote origin $BR | cut -f1); QF=${TMPDIR:-/tmp}/v8fdag2_queue_dry_$T.cmd
    git -C $MIRROR show "$T:$PK/code/v8f_mini_box2_queue.cmd" > "$QF" || { echo "ZZV8FMINI-STOP no queue at the tip"; exit 1; }
  fi
  echo "== the DAG-read predicate (reads $DAG_READ, pinned sha256 $DAG_READ_SHA)"
  dag_pred || { echo "ZZV8FMINI-STOP the DAG-read predicate refuses: $DAG_OUT (a real run would stop here)"; exit 1; }
  echo "-> DAG read $DAG_NAME: arm DAG2 runs at p = $PVAL"
  echo "== predecessor"; echo "wait for ${AFTER_OUT:-<UNSET: a real run REFUSES to start without AFTER_OUT>}: ^${AFTER_DONE:-ZZV8FMINI-DONE} (stop on ^${AFTER_STOP:-ZZV8FMINI-STOP})"
  echo "== checkpoint sha256 (asserted on box 2 before the banks and after the last run)"
  for s in 0 1; do echo "M2b_s${s}_dag $R/M2b_s${s}_dag/ckpt_last.pt ${CKPT_SHA[$s]} (argv.json ${ARGV_SHA[$s]}, summary.json ${SUMM_SHA[$s]})"; done
  echo "== launch-gate token (written by the chain, one per run, after the gate's assertions pass; never by hand)"
  echo '{"kind": "launch-gate-token", "verdict": "PASS", "binding": {"commit": "<the remote tip, 40 hex>", "argv_sha256": "<launch_gate.argv_sha256 of THE TRAINING ARGV as pinned by box 2>", "data_sha256": "<the gate selfcheck'"'"'s info.train_sha256>"}, ...}'
  for s in 0 1; do
    echo "== bank s$s"; echo "-- bankdag2 $s"; dry_stage "$QF" "" bankdag2 $s | grep -a 'v8f_dagger_queue_tool.py' || { echo "ZZV8FMINI-STOP the queue prints no bank line for s$s"; exit 1; }
    echo "-- fetch (all the judge reads), then judge, then PUBLISH into $ART/bank_s$s/ only if the judge passes:"
    $PY "$(cygpath -m $CHECKS)" bank-plan | sed 's/^/   /' || { echo "ZZV8FMINI-STOP bank-plan failed"; exit 1; }
  done
  for run in "${RUNS[@]}"; do
    set -- $run; arm=$1; s=$2; sh=DAG_DRY_SHA$s; sha=${!sh:-}
    plan "$QF" $arm $s "$sha" || { echo "ZZV8FMINI-STOP the queue prints no gate / train / eval line for $(rn $arm $s)"; exit 1; }
    echo "== $(rn $arm $s): $([ $arm = dag2 ] && echo "--dagger-p $PVAL") init $R/M2b_s${s}_dag/ckpt_last.pt (${CKPT_SHA[$s]}), tag $(rt $arm $s)${sha:+, bank sha256 $sha}"
    echo "-- gatedag $arm $s"; echo "$GL"
    echo "-- traindag $arm $s"; echo "$TL"
    echo "-- evaldag $arm $s"; echo "$EL"
    printf '%s' "$TL" > ${TMPDIR:-/tmp}/v8fdag2_tl_$$.txt; printf '%s' "$GL" > ${TMPDIR:-/tmp}/v8fdag2_gl_$$.txt
    echo "-- token argv_sha256 (the training argv): $(argvsha ${TMPDIR:-/tmp}/v8fdag2_tl_$$.txt)"
    same=$($PY "$(cygpath -m $CHECKS)" argv-same "$(cygpath -m ${TMPDIR:-/tmp}/v8fdag2_gl_$$.txt)" "$(cygpath -m ${TMPDIR:-/tmp}/v8fdag2_tl_$$.txt)"); echo "-- gate argv = training argv with --out and --selfcheck-only changed: $same"
