echo "$(date '+%m-%d %H:%M') code archive $B/repo_v8fdag2_tip.tar: $tsz bytes, ${#EXPORT[@]} paths"
$SCP $B/repo_v8fdag2_tip.tar tanitad-box2:D:/tanitad/repo_v8fdag2_tip.tar || stop "ship the code archive"
printf '@echo off\r\necho ===== refresh %s %%DATE%% %%TIME%%\r\ntar -xf D:\\tanitad\\repo_v8fdag2_tip.tar -C D:\\tanitad\\repo\r\nset RC=%%ERRORLEVEL%%\r\necho %s> D:\\tanitad\\repo\\TIP_V8FDAG2.txt\r\necho ===== ZZJOB-END %%DATE%% %%TIME%% rc=%%RC%%\r\n' "$T" "$T" > $B/v8fdag2${TAG}_refresh.cmd
$SCP $B/v8fdag2${TAG}_refresh.cmd tanitad-box2:D:/tanitad/jobs/ || stop "ship refresh job"
launch v8fdag2${TAG}_refresh || stop "launch refresh"
waitrc v8fdag2${TAG}_refresh 40
KEYSHA=""
for f in stack/scripts/v8f_mini_train.py stack/scripts/v8f_mini_eval.py stack/scripts/v8f_dagger_bank.py stack/scripts/v8f_dagger_queue_tool.py stack/scripts/v8f_t1_eval.py stack/tanitad/models/v8f_mini.py stack/tanitad/data/v8f_mini_data.py \
         stack/tanitad/data/v8f_dagger.py stack/tanitad/models/hjepa.py "$PK/code/v8f_mini_box2_queue.cmd" "$PK/raw/eval_grid_windows.json" "$HJ/raw/p10_yaw4512/p10_prior.pt" "$HJ/raw/p10_yaw4512/p10_eval_pred6.npy"; do
  l=$(git -C $MIRROR show "$T:$f" | sha256sum | cut -c1-64)
  [ "$l" = "$(rsha "D:/tanitad/repo/$f" SHA256)" ] || stop "box 2 $f != tip $T"
  KEYSHA="$KEYSHA\"$f\": \"$l\", "
done
for kv in v9_labels_train.npz=83e30bd3791f0767707eade5f4671759 v9_labels_eval139.npz=6b5c7f207cffc3b7eb3cd527fd433599; do
  [ "${kv#*=}" = "$(rsha "D:/tanitad/data/v9/${kv%%=*}" MD5)" ] || stop "box 2 v9 ${kv%%=*} md5 != ${kv#*=}"
done
echo "$(date '+%m-%d %H:%M') box 2 code = tip $T (13 key files sha-checked; both v9 releases md5-checked)"
# ---- 2. the base is fixed (PREREG_V8F_DAGGER2 section 1): the bank generators and all four fine-tunes start from the banked DAG runs (box 2 is idle: a different file costs nothing)
rm -f $CK
ckptsha_b "before the banks"
for s in 0 1; do      # the dev box's pulled copy of DAG (also what the gate assertions compare the new gates with) IS the banked run: summary.json is staged as the comparator "B"
  mkdir -p $E/runs/M2b_s$s
  for f in ckpt_last.pt argv.json summary.json; do
    case $f in ckpt_last.pt) exp=${CKPT_SHA[$s]} ;; argv.json) exp=${ARGV_SHA[$s]} ;; *) exp=${SUMM_SHA[$s]} ;; esac
    [ -f "$DAG1_DIR/M2b_s${s}_dag/$f" ] || stop "the pulled DAG run $DAG1_DIR/M2b_s${s}_dag/$f is missing"
    g=$(sha256sum "$DAG1_DIR/M2b_s${s}_dag/$f" | cut -c1-64); [ "$g" = "$exp" ] || stop "the dev box's $DAG1_DIR/M2b_s${s}_dag/$f sha256 $g != SHA256SUMS.txt's $exp"
  done
  cp "$DAG1_DIR/M2b_s${s}_dag/summary.json" $E/runs/M2b_s$s/summary.json || stop "stage DAG_s$s/summary.json as the gate comparator"
done
fr=$($SSH "powershell -NoProfile -Command \"[int]((Get-PSDrive D).Free / 1GB)\"" 2>/dev/null | tr -d '\r' | grep -E '^[0-9]+$' | head -1)
[ -n "$fr" ] && [ "$fr" -ge $MIN_FREE_GB ] || stop "box 2's D: has '$fr' GB free (< $MIN_FREE_GB): two banks (~0.7 GB each, ESTIMATED), four checkpoints and the evals need room"
$SSH "powershell -NoProfile -Command \"if (Test-Path D:/tanitad/logs/telemetry.stop) { Remove-Item D:/tanitad/logs/telemetry.stop }\"" 2>/dev/null
launch telemetry_long || echo "$(date '+%m-%d %H:%M') telemetry did not launch"
tl() { $SSH "powershell -NoProfile -Command \"Get-Content D:/tanitad/logs/telemetry_full.csv -Tail 1\"" 2>/dev/null | tr -d '\r'; }
sleep 45; t1=$(tl); sleep 35; t2=$(tl)
[[ $t2 == 20* && $t2 != "$t1" ]] || stop "no fresh telemetry ($t1 / $t2): the temperature guard would be blind"
grep -qF "'^(ZZV8FMINI|" $B/v8f_guard_dag2.sh || stop "v8f_guard_dag2.sh does not know this chain's markers (anchored): it would never exit"
grep -qF 'v8f_dagger_bank|v8f_dagger_queue_tool' $B/v8f_guard_dag2.sh || stop "v8f_guard_dag2.sh would not stop the bank generators on a temperature stop"
echo "" > $CUR
V8F_CHAIN_OUT=$L/chain_v8f_dag2.out V8F_CURRENT=$CUR bash $B/v8f_guard_dag2.sh > $L/v8fdag2_guard.out 2>&1 &
# ---- 3. THE BANKS (they depend only on M2b and the TRAIN cache), then the controls and the COVERAGE gate: BLOCKED / REFUSED stop the chain BEFORE any gate or training
declare -a BSHA
for s in 0 1; do bank_one $s; done
judge_banks "$ART/bank_s0" "$ART/bank_s1"; jr=$?
if [ $jr != 0 ]; then
  $PY -c "import json,sys;json.dump({'outcome':'BLOCKED' if sys.argv[1]=='3' else 'REFUSED','bank_sha256':{'s0':sys.argv[2],'s1':sys.argv[3]},'dag_read':sys.argv[4]},open(sys.argv[5],'w'),indent=1)" $jr "${BSHA[0]}" "${BSHA[1]}" "$DAG_NAME" "$(cygpath -m $ART/DAG_OUTCOME.json)"
  stop "$([ $jr = 3 ] && echo BLOCKED || echo REFUSED) at the bank stage (judge rc $jr): no gate was queued, nothing was trained (see $ART/DAG_OUTCOME.json)"
fi
# ---- 3b. only a bank that passed every control and COVERAGE is published to the dev box: the shard npz (the reader's K-B3.1 reads the clip names out of them), then SHA256SUMS.txt over all 11 files, per seed
for s in 0 1; do publish_bank_one $s; done
# ---- 4. the DAG read AGAIN (byte-identical), then ALL FOUR GATES, each asserted and tokened, before ANY training
o2=$(sha256sum "$DAG_READ" | cut -c1-64); [ "$o2" = "$DAGR_SHA" ] || stop "DAG_READ.json changed while the banks ran ($DAGR_SHA -> $o2): re-run the predicate"
for run in "${RUNS[@]}"; do set -- $run; gate_one $1 $2; done
# ---- 5. the four runs, in the PREREG's order; nothing is conditional on a read
for run in "${RUNS[@]}"; do set -- $run; runone $1 $2; done
ckptsha_b "after the last run"
echo "$(date '+%m-%d %H:%M') summary: $(for run in "${RUNS[@]}"; do set -- $run; echo -n "$(rn $1 $2)=$(ckget "$(rt $1 $2)_after_evals" | cut -c1-12) "; done)"
finish "PREREG_V8F_DAGGER2: banks s0/s1 of DAG (COVERAGE >= 0.5; PROVENANCE.json, bank.json, shard provenance and shard npz published), DAG2 (p $PVAL) / DAG2-0 x seeds 0 and 1 trained (3,000 steps each, from DAG), T0-evaluated (standard) and pulled to $ART (sha256 in each SHA256SUMS.txt); the T1-kin rollouts and the reader run on the dev box (NOT here)"
